Bind(y,A,B)[x:=N]=
\begin{cases}
Bind(y,A',B),&y=x,\\
Bind(y,A',B[x:=N]),&y\ne x,\ y\notin FV(N),\\
Bind(z,A',(B[y:=z])[x:=N]),&y\ne x,\ y\in FV(N).
\end{cases}

(let\ y=P\ in\ Q)[x:=N]=
\begin{cases}
let\ y=P[x:=N]\ in\ Q,&y=x,\\
let\ y=P[x:=N]\ in\ Q[x:=N],&y\ne x,\ y\notin FV(N),\\
let\ z=P[x:=N]\ in\ (Q[y:=z])[x:=N],&y\ne x,\ y\in FV(N).
\end{cases}

\frac{E(f)=(\langle(x_i,A_i)\rangle_{i<n},B,P)\quad |\bar M|=n\quad
E\vdash\operatorname{SubSeq}_{LFSC}(P,\bar x,\bar M)\Downarrow V}
{E\vdash\mathsf{call}(f,\bar M)\Downarrow V}.

\mathsf{Rule}^{SC}_{LFSC,\mathsf{call}}
=
\left\{
(\langle E\vdash\operatorname{SubSeq}_{LFSC}(P,\bar x,\bar M)\Downarrow V\rangle,
E\vdash\mathsf{call}(f,\bar M)\Downarrow V):
\begin{array}{l}
E\in\mathsf{SCEnv}_{LFSC},\ \mathsf{SCEnvOK}_{LFSC}(E),\\
E(f)=(\langle(x_i,A_i)\rangle_{i<n},B,P),\
|\bar M|=n,\ \bar M\in\mathsf{Obj}_{SC}^{n}
\end{array}
\right\},

\mathsf{SCTrace}_{LFSC}
=
\left\{
(E,P,M,\tau):
\begin{array}{l}
E\in\mathsf{SCEnv}_{LFSC},\ \kappa\in EnvCert(E),\
P\in\mathsf{SCProg}_{LFSC},\ M\in\mathsf{Obj}_{SC},\\
C_0=(E,P,\epsilon),\ C_m=(E,\mathsf{return}\ M,\epsilon),\\
\forall i<m\ (C_i,L_i,C_{i+1})\in\mathsf{SCStep}_{LFSC}
\end{array}
\right\}.

\frac{\Gamma,x:A\vdash M:B}
{\Gamma\vdash\lambda x:A.M:\Pi x:A.B},
\qquad
\frac{\Gamma\vdash M:\Pi x:A.B\quad \Gamma\vdash N:A}
{\Gamma\vdash M\,N:\operatorname{Sub}_{LFSC}(B,x,N)}.

\mathsf{Rule}_{SCObj}^{LFSC}
=
\left\{
\left(
\langle\Gamma\vdash M_i:SubSeq(A_i,\bar x_{<i},\bar M_{<i})\rangle_{i<n}
\mathbin{^\frown}\left\langle
E\vdash\operatorname{SubSeq}_{LFSC}(P,\bar x,\bar M)\Downarrow^{\tau}_{\mathsf{tr}}N,
\Gamma\vdash N:\operatorname{SubSeq}_{LFSC}(B,\bar x,\bar M)
\right\rangle,

\Gamma\vdash\mathsf{sc}(f,\bar M):\operatorname{SubSeq}_{LFSC}(B,\bar x,\bar M)
\right):
\begin{array}{l}
E\in\mathsf{SCEnv}_{LFSC},\ \mathsf{SCEnvOK}_{LFSC}(E),\\
\Gamma\in\mathsf{Ctx}_{LFSC},\ N\in\mathsf{Obj}_{SC},\\
E(f)=(\langle(x_i,A_i)\rangle_{i<n},B,P),\
\bar M\in\mathsf{Obj}_{SC}^{n},\\
(E,\operatorname{SubSeq}_{LFSC}(P,\bar x,\bar M),N,\tau)
\in\mathsf{SCTrace}_{LFSC}
\end{array}
\right\}.
